import React, { useState, useEffect } from 'react';
import Navbar from '../components/Navbar';
import { FaPlus, FaCheckCircle, FaCircle, FaTrash, FaPlay, FaPause, FaRedo, FaStopwatch, FaHourglassHalf } from 'react-icons/fa';

function Habits() {
  const [habits, setHabits] = useState([
    { id: 1, name: '💧 Drink Water', target: '8 glasses', completed: false, timerActive: false, timerElapsed: 0, targetMinutes: 0 },
    { id: 2, name: '🏃 Exercise', target: '30 mins', completed: false, timerActive: false, timerElapsed: 0, targetMinutes: 30 },
    { id: 3, name: '🧘 Meditate', target: '10 mins', completed: false, timerActive: false, timerElapsed: 0, targetMinutes: 10 },
    { id: 4, name: '📚 Read Book', target: '20 pages', completed: false, timerActive: false, timerElapsed: 0, targetMinutes: 0 },
  ]);
  const [newHabit, setNewHabit] = useState('');
  const [newHabitTime, setNewHabitTime] = useState('');
  const [celebrating, setCelebrating] = useState(null);

  // Stopwatch timer effect - counts UP
  useEffect(() => {
    const intervals = [];
    habits.forEach(habit => {
      if (habit.timerActive && !habit.completed) {
        const interval = setInterval(() => {
          setHabits(prev => prev.map(h => {
            if (h.id === habit.id) {
              const newElapsed = h.timerElapsed + 1;
              // Auto-complete when reaching target time
              if (h.targetMinutes > 0 && newElapsed >= h.targetMinutes) {
                return { ...h, timerElapsed: h.targetMinutes, timerActive: false, completed: true };
              }
              return { ...h, timerElapsed: newElapsed };
            }
            return h;
          }));
        }, 60000); // Update every minute
        intervals.push(interval);
      }
    });
    
    // Check for newly completed habits to show celebration
    habits.forEach(habit => {
      if (habit.completed && habit.timerElapsed >= habit.targetMinutes && habit.targetMinutes > 0) {
        setCelebrating(habit.id);
        setTimeout(() => setCelebrating(null), 3000);
      }
    });
    
    return () => intervals.forEach(clearInterval);
  }, [habits]);

  const toggleHabit = (id) => {
    setHabits(habits.map(habit =>
      habit.id === id ? { ...habit, completed: !habit.completed, timerActive: false } : habit
    ));
    if (!habits.find(h => h.id === id).completed) {
      setCelebrating(id);
      setTimeout(() => setCelebrating(null), 2000);
    }
  };

  const startTimer = (id) => {
    setHabits(habits.map(habit =>
      habit.id === id && !habit.completed
        ? { ...habit, timerActive: true }
        : habit
    ));
  };

  const pauseTimer = (id) => {
    setHabits(habits.map(habit =>
      habit.id === id ? { ...habit, timerActive: false } : habit
    ));
  };

  const resetTimer = (id) => {
    setHabits(habits.map(habit =>
      habit.id === id ? { ...habit, timerElapsed: 0, timerActive: false, completed: false } : habit
    ));
  };

  const addHabit = () => {
    if (newHabit.trim()) {
      const timeInMinutes = parseInt(newHabitTime) || 0;
      setHabits([...habits, {
        id: Date.now(),
        name: newHabit,
        target: timeInMinutes > 0 ? `${timeInMinutes} mins` : 'Daily',
        completed: false,
        timerActive: false,
        timerElapsed: 0,
        targetMinutes: timeInMinutes
      }]);
      setNewHabit('');
      setNewHabitTime('');
    }
  };

  const deleteHabit = (id) => {
    setHabits(habits.filter(habit => habit.id !== id));
  };

  const formatTime = (minutes) => {
    if (minutes <= 0) return '0m';
    const hrs = Math.floor(minutes / 60);
    const mins = minutes % 60;
    if (hrs > 0) return `${hrs}h ${mins}m`;
    return `${mins}m`;
  };

  const getTimerProgress = (habit) => {
    if (habit.targetMinutes === 0) return 0;
    return (habit.timerElapsed / habit.targetMinutes) * 100;
  };

  const completedCount = habits.filter(h => h.completed).length;

  return (
    <div style={styles.container}>
      <Navbar />
      
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}>✅ Habit Tracker</h1>
          <p style={styles.subtitle}>Track your habits with a stopwatch timer</p>
        </div>

        {celebrating && (
          <div style={styles.celebrationOverlay}>
            <div style={styles.celebrationText}>
              🎉 Great Job! 🎉
            </div>
            <div style={styles.confettiContainer}>
              {[...Array(30)].map((_, i) => (
                <div key={i} style={{...styles.confetti, left: `${Math.random() * 100}%`, animationDelay: `${Math.random() * 2}s`, backgroundColor: `hsl(${Math.random() * 360}, 70%, 50%)`}} />
              ))}
            </div>
          </div>
        )}

        <div style={styles.progressCard}>
          <div style={styles.progressInfo}>
            <span>📊 Daily Progress</span>
            <span>{completedCount}/{habits.length} completed</span>
          </div>
          <div style={styles.progressBar}>
            <div style={{...styles.progressFill, width: `${(completedCount/habits.length)*100}%`}} />
          </div>
        </div>

        <div style={styles.addHabitCard}>
          <div style={styles.addHabitInputs}>
            <input
              type="text"
              placeholder="Add a new habit..."
              style={styles.input}
              value={newHabit}
              onChange={(e) => setNewHabit(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && addHabit()}
            />
            <input
              type="number"
              placeholder="Target minutes"
              style={styles.timeInput}
              value={newHabitTime}
              onChange={(e) => setNewHabitTime(e.target.value)}
            />
          </div>
          <button onClick={addHabit} style={styles.addBtn}>
            <FaPlus /> Add Habit
          </button>
        </div>

        <div style={styles.habitsList}>
          {habits.map(habit => {
            const progress = getTimerProgress(habit);
            const isActive = habit.timerActive;
            const isCompleted = habit.completed;
            const hasTarget = habit.targetMinutes > 0;
            
            return (
              <div key={habit.id} style={{...styles.habitItem, ...(isCompleted ? styles.habitCompleted : {}), ...(isActive ? styles.habitActive : {})}}>
                <div style={styles.habitLeft}>
                  <div onClick={() => toggleHabit(habit.id)} style={styles.checkbox}>
                    {isCompleted ? 
                      <FaCheckCircle color="#2ecc71" size={28} /> : 
                      <FaCircle color="#ccc" size={28} />
                    }
                  </div>
                  <div style={styles.habitInfo}>
                    <h4 style={{...styles.habitName, textDecoration: isCompleted ? 'line-through' : 'none'}}>
                      {habit.name}
                    </h4>
                    <p style={styles.habitTarget}>🎯 {habit.target}</p>
                    
                    {hasTarget && (
                      <div style={styles.timerSection}>
                        {/* Animated Progress Bar */}
                        <div style={styles.timerBar}>
                          <div 
                            style={{
                              ...styles.timerFill, 
                              width: `${progress}%`,
                              transition: 'width 0.3s ease-out'
                            }} 
                          />
                        </div>
                        
                        {/* Timer Display */}
                        <div style={styles.timerInfo}>
                          <FaStopwatch size={14} color={isActive ? '#2ecc71' : '#667eea'} />
                          <span style={styles.timerElapsedText}>
                            {formatTime(habit.timerElapsed)} elapsed
                          </span>
                          {habit.targetMinutes > 0 && (
                            <span style={styles.timerTargetText}>
                              / {formatTime(habit.targetMinutes)}
                            </span>
                          )}
                        </div>
                        
                        {/* Timer Controls */}
                        <div style={styles.timerControls}>
                          {!isActive && !isCompleted && habit.timerElapsed < habit.targetMinutes && (
                            <button onClick={() => startTimer(habit.id)} className="btn-play" style={styles.timerBtnPlay}>
                              <FaPlay size={12} /> Start
                            </button>
                          )}
                          {isActive && (
                            <button onClick={() => pauseTimer(habit.id)} style={styles.timerBtnPause}>
                              <FaPause size={12} /> Pause
                            </button>
                          )}
                          {habit.timerElapsed > 0 && (
                            <button onClick={() => resetTimer(habit.id)} style={styles.timerBtnReset}>
                              <FaRedo size={12} /> Reset
                            </button>
                          )}
                        </div>
                        
                        {/* Milestone Animation */}
                        {progress > 0 && progress < 100 && isActive && (
                          <div style={styles.movingGraphic}>
                            <div style={{...styles.movingDot, left: `${progress}%`}}>
                              <FaHourglassHalf size={12} />
                            </div>
                          </div>
                        )}
                      </div>
                    )}
                    
                    {/* Achievement Badge */}
                    {isCompleted && habit.targetMinutes > 0 && habit.timerElapsed >= habit.targetMinutes && (
                      <div style={styles.completedBadge}>
                        🏆 Completed {formatTime(habit.targetMinutes)} goal!
                      </div>
                    )}
                  </div>
                </div>
                <button onClick={() => deleteHabit(habit.id)} style={styles.deleteBtn}>
                  <FaTrash color="#e74c3c" size={18} />
                </button>
              </div>
            );
          })}
        </div>

        {habits.length === 0 && (
          <div style={styles.emptyState}>
            <p>✨ No habits yet. Add your first habit above! ✨</p>
          </div>
        )}

        <div style={styles.tipsCard}>
          <div style={styles.tipIcon}>⏱️</div>
          <div style={styles.tipContent}>
            <h4>Stopwatch Timer</h4>
            <p>Click Start to begin tracking. Watch the progress bar fill up and the moving graphic slide across!</p>
          </div>
        </div>
      </div>
    </div>
  );
}

